/**
 * Selects this line item's display image, always returning a defined `alt` even when there is no
 * image at all (unlike `productListCardMapper.ts`'s `toCardImage`, which returns `undefined` for
 * the whole image on a miss — a PLP card can legitimately skip rendering entirely when it has
 * nothing to show; a cart line item cannot, per this step's own pass criteria).
 *
 * The lookup itself reuses `findImageGroupBy` exactly as
 * `overrides/app/components/item-variant/item-image.tsx:70-73` already does (same `viewType:
 * 'small'` / `selectedVariationAttributes` call) rather than reimplementing image-group matching.
 */
const selectCartItemImage = (item: CartLineItem): CartItemImage => {
  const image = findImageGroupBy(item.imageGroups, {
    viewType: 'small',
    selectedVariationAttributes: item.variationValues,
  })?.images?.[0];

  return {
    src: image?.disBaseLink || image?.link,
    alt: image?.alt || item.productName || item.name || '',
  };
};

/**
 * Combines the colour and size variation values into the single string the Figma cart-item spec
 * calls for, reusing the exact mechanism
 * `overrides/app/components/item-variant/item-attributes.tsx:98,148-150` already uses for its own
 * `combineAttributeValues` behaviour (`getDisplayVariationValues(...)` then
 * `Object.values(...).join(', ')`) rather than reimplementing string-combining from scratch.
 *
 * Ordering is inherited from that same call, not independently re-sorted here: it reflects
 * whichever order the incoming `variationValues` object's own keys are in (see
 * `getDisplayVariationValues`'s `Object.entries(values).reduce(...)`,
 * `node_modules/@salesforce/retail-react-app/app/utils/product-utils.js:30`). This is the
 * identical mechanism `item-attributes.tsx`'s own docblock (line 31) already cites as producing
 * "Lilac Sand, One size" (colour, size) for real Zimmermann catalog data —
 * `product-item/index.tsx`'s docblock (line 44) corroborates the same combined-string behaviour
 * generically ("colour, size") without repeating that specific example. This function inherits
 * that already-verified behaviour rather than re-guaranteeing the order independently.
 */
const selectCombinedAttributes = (item: CartLineItem): string => {
  const variationValues = getDisplayVariationValues(item.variationAttributes, item.variationValues);
  return variationValues ? Object.values(variationValues).join(', ') : '';
};

/**
 * Maps one basket line item (already merged with its full product data — see this file's own
 * module docblock) to a plain display-data shape: image, name, one combined colour/size string,
 * and quantity/stepQuantity passed through. Pure function, no hooks — keeps every consumer in B3
 * prop-driven with no data-fetching hook in a leaf, per this step's own plan text.
 */
export const selectCartItemProps = (item: CartLineItem): CartItemMapperResult => ({
  itemId: item.itemId,
  productId: item.productId,
  name: item.productName || item.name || '',
  image: selectCartItemImage(item),
  combinedAttributes: selectCombinedAttributes(item),
  quantity: item.quantity,
  stepQuantity: item.stepQuantity,
});

